        sonya_endLight: { text: 'सोन्या ने माफ़ किया — इसलिए नहीं कि यह आसान था, या माँ ने कुछ ऐसा किया था जो माफ़ी के क़ाबिल हो, बल्कि इसलिए कि उसने तय किया कि वह बाक़ी ज़िंदगी किसी और के अपराधबोध को अपना बोझ नहीं बनाएगी। आज वह मुश्किल हालात में फंसे किशोरों के आश्रयों में जाती है और उन्हें वह बात कहती है जो उसे कभी किसी ने नहीं कही: कि उनकी ज़िंदगी ग़लती नहीं है, भले ही किसी ने कभी कुछ और तय किया हो। सोन्या की कहानी यहाँ समाप्त होती है।', next: null, choices: [] },
        sonya_endDark: { text: 'सोन्या उस दिन बिना पीछे मुड़े चली गई, और फिर कभी उस नंबर से आए फ़ोन का जवाब नहीं दिया। सालों बाद भी, वह दूसरों के बच्चों के खेल के मैदान में "माँ" शब्द सुनकर चौंक जाती है, और जो भी उसके क़रीब आने की कोशिश करता है उससे दूरी बनाए रखती है — सुरक्षित, पर पूरी तरह अकेली। सोन्या की कहानी यहाँ समाप्त होती है।', next: null, choices: [] },
