        kristina_endLight: { text: 'कृतिका ने विश्वास स्वीकार किया — और जैसा उसे डर था, उसने अपना स्थायी पद और उस बिरादरी का ज़्यादातर हिस्सा खो दिया जिसे वह बीस साल से अपना समुदाय कहती आई थी। उसने बाद में ख़ुद इसे किसी सौम्य आध्यात्मिक सफ़र के बजाय "ट्रेन दुर्घटना" कहा — सालों बाद भी इससे नरम कोई शब्द नहीं मिला — जिसके बाद आख़िरकार शून्य से कुछ असली बनाना मुमकिन हुआ। कृतिका की कहानी यहाँ समाप्त होती है।', next: null, choices: [] },
        kristina_endDark: { text: 'कृतिका ने बाइबल पूरी पढ़े बिना एक तरफ़ रख दी और अपने पुराने लेखों और ख़ुद पर अपने पुराने यक़ीन में लौट गई। वह अब भी कभी-कभी पादरी और उसकी पत्नी को छोटी चिट्ठियाँ लिखती है — बस वह ख़ुद को भी नहीं समझा पाती कि वह इस अजीब दोस्ती को पूरी तरह क्यों नहीं तोड़ पाती, जो उससे कुछ नहीं माँगती। कृतिका की कहानी यहाँ समाप्त होती है।', next: null, choices: [] },
