        polina_endLight: { text: 'पूजा अपनी व्हीलचेयर में मंच तक गई और बिना कोई पर्दा डाले सब कुछ बताया, हर विधायक की आँखों में बारी-बारी देखते हुए। उसके शब्द सुनवाई के आधिकारिक रिकॉर्ड में दर्ज हुए, और बाद में उसकी उम्र की एक लड़की काँपते हुए उसके पास आई और बताया कि उसने भी पिछले हफ़्ते वही सोचा था — और उसकी बात सुनकर अपना इरादा बदल दिया। आज पूजा पूरे देश में युवाओं और विधायकों की सभाओं में बोलती है, यह कोशिश करते हुए कि संकट में फंसे दूसरे किशोरों को, जैसी वह सोलह साल की उम्र में थी, समय पर मदद मिले। पूजा की कहानी यहाँ समाप्त होती है।', next: null, choices: [] },
        polina_endDark: { text: 'पूजा ने समिति के सामने बोलने से इनकार कर दिया और जीना जारी रखा, निशानों को कपड़ों के नीचे छुपाते हुए और कहानी को हमेशा जैसी चुप्पी के नीचे। सुनवाई उसकी गवाही के बिना हुई, और उस साल प्रस्तावित उपाय पास नहीं हो पाए। पूजा की कहानी यहाँ समाप्त होती है।', next: null, choices: [] },
