        viktor_endLight: { text: 'विक्रम ने माना: ऐसी जाँच के बाद नास्तिक बने रहने के लिए ईसाई बनने से भी ज़्यादा अंधा विश्वास चाहिए होगा — और उसकी पेशेवर ईमानदारी अब इसकी इजाज़त नहीं दे सकती थी। उसने पत्रकारिता छोड़ दी ताकि दूसरों को वही जाँच समझा सके जिसने उसकी अपनी ज़िंदगी बदल दी, और अपने दो साल के शोध को एक किताब में बदल दिया, उसी क़ानूनी सबूत की भाषा में लिखी जिसमें वह कभी अपनी रिपोर्ट लिखता था। विक्रम की कहानी यहाँ समाप्त होती है।', next: null, choices: [] },
