        vika_endLight: { text: 'विद्या लगभग दस साल तक चली हिरासत की लड़ाई से गुज़री, और इस पूरे समय वह एक ऐसे विश्वास से जुड़ी रही जो उसे इस थकाऊ संघर्ष जितना ही वास्तविक लगता था। आज वह अपने जैसी दूसरी महिलाओं के साथ मिलकर, ऐसे ही विवाह से निकली विश्वासी माँओं के लिए, जो तलाक़ से गुज़र रही हैं, एक सहायता सेवा चलाती है — हिरासत की सुनवाइयों की तैयारी के लिए तैयार सामग्री के साथ, ताकि किसी और को उसकी तरह पूरी तरह अकेले यह सब दोबारा न समझना पड़े। विद्या की कहानी यहीं समाप्त होती है।', next: null, choices: [] },
