        inna_choice2: { text: 'पाँचवें गर्भपात और एक और असफल इलाज के बाद, डॉक्टर बिना किसी उम्मीद जगाने वाली शर्त के साफ़ कहता है: प्राकृतिक गर्भधारण की संभावना बेहद कम है। संयोग से उसकी डायरी पढ़ने वाला एक प्रकाशक इशिका को उसके निजी लेखन को उसी कहानी से गुज़र रही हज़ारों महिलाओं के लिए एक किताब में बदलने का प्रस्ताव देता है — लेकिन इसके लिए स्कारलेट का नाम और रसोई के फ़र्श पर हुई वे शाम की प्रार्थनाएँ भी, अब सहेलियों के छोटे दायरे को नहीं, बल्कि पूरी तरह अजनबियों को बतानी होंगी।', choices: [
          { label: 'राज़ी होना और अपने निजी दुख को दूसरों के लिए एक किताब में बदलना', effects: { faith: 15 }, next: 'inna_endLight' },
          { label: 'मना कर देना — कुछ चीज़ें अजनबियों की नज़रों के लिए बहुत निजी हैं', effects: { faith: -15 }, next: 'inna_endDark' },
        ] },
        inna_endLight: { text: 'इशिका राज़ी हो गई और किताब लिखी, पाठकों की सुविधा के लिए कुछ भी नरम किए बिना, स्कारलेट वाले अध्याय और अपनी ही रसोई के फ़र्श पर फिर से प्रार्थना करना सीखने की कहानी समेत। यह किताब हज़ारों महिलाओं तक पहुँची, जिन्होंने पहली बार पढ़ा कि अजन्मे बच्चे के लिए शोक मनाना विश्वास की कमज़ोरी नहीं, बल्कि उस तक पहुँचने के ईमानदार रास्ते का हिस्सा है। आज भी वह हर शाम उसी सहेली के साथ प्रार्थना करती है, और मातृत्व उस तरह नहीं आया जैसी उसने सालों योजना बनाई थी, लेकिन वह सचमुच आया — एक ऐसी बच्ची को गोद लेकर जो बिना माता-पिता के रह गई थी। इशिका की कहानी यहीं समाप्त होती है।', next: null, choices: [] },
