        yuriy_endLight: { text: 'योगेश रुक गया और उसी तबाह हो चुके शहर में सेमिनरी चलाना जारी रखा, नए पादरियों को उन आवाज़ों के बीच प्रशिक्षित करते हुए जो आस-पास सबके लिए बहुत पहले एक जानी-पहचानी पृष्ठभूमि बन चुकी थीं। बाद में उसने इन सालों की अपनी डायरी को एक किताब में समेटा — जीत की कहानी नहीं, बल्कि परमेश्वर से बिना तैयार जवाबों वाले सवालों के साथ एक ईमानदार विलाप, और यह बयान कि कैसे बिल्कुल अजनबी लोगों के हाथ बार-बार ठीक तभी उसके पास आ पहुँचे जब उसकी अपनी ताक़त ख़त्म हो चुकी थी। योगेश की कहानी यहीं समाप्त होती है।', next: null, choices: [] },
        yuriy_endDark: { text: 'योगेश सेमिनरी और बचे हुए छात्रों को विदेश ले गया, गोलाबारी के बीच सेवा जारी रखने की बजाय सुरक्षा को चुनते हुए। कक्षाएँ कहीं ज़्यादा शांत माहौल में फिर शुरू हुईं, लेकिन वह मानता है कि उसका एक हिस्सा उसी तबाह हो चुके शहर में रह गया, जिसे उसने आख़िरकार छोड़ दिया। योगेश की कहानी यहीं समाप्त होती है।', next: null, choices: [] },
