        gleb_endLight: { text: 'गोपाल ने मैनेजमेंट और फैंस के विरोध के बावजूद बैंड पूरी तरह छोड़ दिया। प्रेस और कुछ आलोचकों ने इसे एक होनहार करियर का अंत कहा, लेकिन उसकी बेटी के लिए यह कहीं ज़्यादा महत्वपूर्ण किसी चीज़ की शुरुआत बनी — एक पिता जो आख़िरकार स्थायी रूप से पास था। गोपाल की कहानी यहीं समाप्त होती है।', next: null, choices: [] },
        gleb_endDark: { text: 'गोपाल फिर भी टूर पर गया, ख़ुद से कहते हुए कि इस बार वह लत को अलग तरीक़े से क़ाबू में रख पाएगा। टूर के बीचोंबीच सब कुछ फिर वैसा ही हो गया — मंच पर जाने से पहले वही ख़ुराक़, और फ़ोन पर बेटी का वही सवाल, जिसका कभी ईमानदार जवाब नहीं मिला। गोपाल की कहानी यहीं समाप्त होती है।', next: null, choices: [] },
