        oleg_endLight: { text: 'ओम ने बिना किसी सजावट के किताब लिखी, उस हादसे के शोक को ईमानदारी से ठीक वैसा ही बताया जैसा वह था — एक ऐसी आपदा जिसने उसके परिवार की तीन पीढ़ियों पर एक साथ वार किया, न कि बस एक कठिनाई जिसे चुपचाप "शांति से स्वीकार" कर लेना था। उसने कुछ ऐसा कहना शुरू किया जिसने कई पाठकों को चौंका दिया: आत्मा ऐसी हानि के बावजूद ही नहीं, बल्कि ठीक उसी के ज़रिए बढ़ सकती है — और इस स्वीकारोक्ति ने अपनी-अपनी आपदाएँ झेल चुके हज़ारों लोगों को यह शर्म महसूस करना छोड़ने में मदद की कि उनका शोक किसी समय-सारणी के हिसाब से नहीं बीत रहा। ओम की कहानी यहीं समाप्त होती है।', next: null, choices: [] },
        oleg_endDark: { text: 'ओम ने किताब से मना कर दिया और अपने दिनों को कामों से भरता रहा, कभी रुककर सचमुच उस घटी हुई बात को जीने के लिए नहीं रुका। सालों बाद बच्चों ने देखा कि पिता किसी भी चीज़ के बारे में बात कर सकते हैं, सिवाय उस एक दिन के जिसने असल में उनकी बाक़ी पूरी ज़िंदगी तय कर दी थी। ओम की कहानी यहीं समाप्त होती है।', next: null, choices: [] },
