        kirill_endLight: { text: 'करण ने सब कुछ जैसा था वैसा बताया, कुछ भी मुलायम बनाए बिना, और यह बातचीत ऐसी ही ईमानदार बातचीतों की एक कड़ी बन गई, जिसने सालों बाद नशे से जूझ रहे लोगों की एक पूरी परस्पर-सहायता मुहिम की नींव रखने में मदद की, जो आज दुनिया भर में जानी जाती है। करण की कहानी यहीं समाप्त होती है।', next: null, choices: [] },
        kirill_endDark: { text: 'करण आम बातों से टल गया और अपने जान-पहचान वाले को अपने पतन की पूरी सच्चाई और यह कि सचमुच क्या चीज़ उसकी मदद करती है या नहीं, कभी बताने की हिम्मत नहीं जुटा पाया। एक मौक़ा जो किसी और की मदद कर सकता था, बस दफ़्तर के बंद दरवाज़े के पीछे एक शालीन बातचीत बनकर रह गया। करण की कहानी यहीं समाप्त होती है।', next: null, choices: [] },
